    red: glow([[0, 'rgba(255,120,100,1)'], [.3, 'rgba(255,40,30,.5)'], [1, 'rgba(255,0,0,0)']]),
    green: glow([[0, 'rgba(170,255,190,1)'], [.3, 'rgba(40,255,90,.45)'], [1, 'rgba(0,255,60,0)']]),
    fire: glow([[0, 'rgba(255,236,190,.95)'], [.2, 'rgba(255,170,70,.75)'], [.5, 'rgba(235,80,18,.32)'], [1, 'rgba(150,20,0,0)']]),
    core: glow([[0, 'rgba(255,255,240,1)'], [.4, 'rgba(255,230,160,.6)'], [1, 'rgba(255,200,120,0)']]),
