      const len = L * (.82 + .18 * Math.sin(i * 2.3 + seed)) * (base > 0 && base < 2 ? .75 : 1);
      const droop = .55 + .25 * Math.max(0, Math.sin(base)), dx = Math.cos(ang), dy = Math.sin(ang);
